//! Parity of kernel trees, GPyTorch's and BoTorch's kernels, priors and
//! constraints in `SingleTaskGP` with BoTorch (fixtures in
//! `tests/fixtures/6a_kernels/*.json`, generated by
//! `scripts/generate_fixtures.py --phase 6a-kernels`).
//!
//! Every fixture describes its `covar_module` as a JSON spec (GPyTorch /
//! BoTorch class names and keyword arguments, see
//! `botorch_pyo3/tests/kernel_tree_helpers.py`), from which this test builds
//! the same [`KernelNode`] tree, and records BoTorch's
//!
//! * parameter names, shapes and optimizer bounds (exact) and default raw
//!   parameters (exact, except the random initial values of index kernels,
//!   which the test takes from the fixture);
//! * MLL values (1e-9, relative) and gradients (1e-8, relative to the largest
//!   component) at the default and at random raw parameters, and the prior
//!   kernel matrix at the random parameters (1e-9);
//! * `q = 1` posterior means and variances (GPyTorch's `diag=True` mode), with
//!   and without observation noise, and their gradients with respect to the
//!   inputs; joint `q = 3` posteriors per output and the gradient of a
//!   weighted sum of their means and covariances (1e-9 values, 1e-8
//!   gradients);
//! * `fit_gpytorch_mll` from the default parameters, compared with BoTorch's
//!   outcomes on the model and 16 twins whose training inputs are perturbed
//!   at 1e-14 .. 1e-11 (first attempts only: retries start from prior
//!   samples drawn by different generators): botorch_rs's best final loss
//!   (on the same twins) must reach BoTorch's best and its own fit must not
//!   end above BoTorch's worst outcome, within max(1e-6, 10 × the spread of
//!   BoTorch's outcomes at its best optimum); on chaotic likelihoods, where
//!   BoTorch's outcomes spread over more than 1e-3, statistically: the best
//!   of botorch_rs's outcomes must reach BoTorch's median and their median
//!   BoTorch's upper quartile (within 1e-6).
//!
//! Run with `--nocapture` to print the error tables.

mod common;

use std::path::PathBuf;

use botorch_core::constraints::{Constraint, GreaterThan, Interval, LessThan, ParameterTransform};
use botorch_core::kernels::{KernelKind, KernelNode, MatrixPrior};
use botorch_core::{
    fit_gpytorch_mll, BatchedMultiOutputGP, BatchedMultiOutputGPOptions, FitOptions, Matrix,
    OutcomeTransformChoice, Prior, Vector,
};
use common::{fixture_dir, matrix, rel_err, Report};
use serde::Deserialize;
use serde_json::Value;

const VALUE_TOL: f64 = 1e-9;
const GRAD_TOL: f64 = 1e-8;
const FIT_TOL: f64 = 1e-6;
const FIT_CLUSTER: f64 = 1e-4;
/// BoTorch's fit outcomes on a model and its twins that spread over more than
/// this (in the final loss) mark a chaotic likelihood (many optima reached
/// depending on rounding), on which the fits are compared statistically.
const CHAOTIC_RANGE: f64 = 1e-3;

/// `(min, lower quartile, median, upper quartile)` of a sample.
fn quantiles(v: &[f64]) -> (f64, f64, f64, f64) {
    let mut s = v.to_vec();
    s.sort_by(f64::total_cmp);
    let q = |p: f64| {
        let pos = p * (s.len() - 1) as f64;
        let (lo, hi) = (pos.floor() as usize, pos.ceil() as usize);
        s[lo] + (s[hi] - s[lo]) * (pos - lo as f64)
    };
    (s[0], q(0.25), q(0.5), q(0.75))
}

#[derive(Deserialize)]
struct Mll {
    value: Vec<f64>,
    grad: Vec<f64>,
}

#[derive(Deserialize)]
struct PosteriorFixture {
    x: Vec<Vec<f64>>,
    mean: Vec<Vec<f64>>,
    variance: Vec<Vec<f64>>,
    variance_noisy: Vec<Vec<f64>>,
    dmean_dx: Vec<Vec<f64>>,
    dvariance_dx: Vec<Vec<f64>>,
    joint_x: Vec<Vec<f64>>,
    joint_mean: Vec<Vec<f64>>,
    joint_covariance: Vec<Vec<Vec<f64>>>,
    joint_covariance_noisy: Vec<Vec<Vec<f64>>>,
    weights_mean: Vec<Vec<f64>>,
    weights_cov: Vec<Vec<Vec<f64>>>,
    djoint_dx: Vec<Vec<f64>>,
}

#[derive(Deserialize)]
struct Fit {
    loss: f64,
    iterations: usize,
    attempts: usize,
    raw_params: Vec<f64>,
    twin_train_x: Vec<Vec<Vec<f64>>>,
    twin_losses: Vec<f64>,
    twin_attempts: Vec<usize>,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    spec: Value,
    m: usize,
    fixed_noise: bool,
    standardize: bool,
    train_x: Vec<Vec<f64>>,
    train_y: Vec<Vec<f64>>,
    train_yvar: Option<Vec<Vec<f64>>>,
    param_names: Vec<(String, Vec<usize>)>,
    bounds: Vec<(Value, Value)>,
    default_raw: Vec<f64>,
    default_mll: Mll,
    raw: Vec<f64>,
    mll: Mll,
    k_train: Value,
    posterior: PosteriorFixture,
    fit: Option<Fit>,
}

fn num(v: &Value) -> f64 {
    match v {
        Value::Number(n) => n.as_f64().unwrap(),
        Value::String(s) => match s.as_str() {
            "inf" => f64::INFINITY,
            "-inf" => f64::NEG_INFINITY,
            "nan" => f64::NAN,
            other => panic!("not a number: {other}"),
        },
        other => panic!("not a number: {other}"),
    }
}

// ----------------------------------------------------------------------
// Building the kernel tree of a spec (mirrors botorch_rs's kernel classes)
// ----------------------------------------------------------------------

fn prior_of(v: &Value) -> Prior {
    let name = v[0].as_str().unwrap();
    let a: Vec<f64> = v[1].as_array().unwrap().iter().map(num).collect();
    let p = match name {
        "GammaPrior" => Prior::gamma(a[0], a[1]),
        "LogNormalPrior" => Prior::log_normal(a[0], a[1]),
        "NormalPrior" => Prior::normal(a[0], a[1]),
        "UniformPrior" => Prior::uniform(a[0], a[1]),
        "HalfCauchyPrior" => Prior::half_cauchy(a[0]),
        "HalfNormalPrior" => Prior::half_normal(a[0]),
        "BetaPrior" => Prior::beta(a[0], a[1]),
        other => panic!("unknown prior {other}"),
    };
    p.unwrap().rounded_to_f32()
}

fn transform_of(kw: &Value, default: Option<ParameterTransform>) -> Option<ParameterTransform> {
    match kw.get("transform") {
        None => default,
        Some(Value::Null) => None,
        Some(Value::String(s)) if s == "softplus" => Some(ParameterTransform::Softplus),
        Some(Value::String(s)) if s == "sigmoid" => Some(ParameterTransform::Sigmoid),
        Some(other) => panic!("unknown transform {other}"),
    }
}

fn constraint_of(v: &Value) -> Constraint {
    let name = v[0].as_str().unwrap();
    let a: Vec<f64> = v[1].as_array().unwrap().iter().map(num).collect();
    let kw = &v[2];
    let init = kw.get("initial_value").map(num);
    match name {
        "Positive" => GreaterThan::new(
            0.0,
            transform_of(kw, Some(ParameterTransform::Softplus)),
            init,
        )
        .rounded_to_f32()
        .into(),
        "GreaterThan" => GreaterThan::new(
            a[0],
            transform_of(kw, Some(ParameterTransform::Softplus)),
            init,
        )
        .rounded_to_f32()
        .into(),
        "LessThan" => LessThan::new(
            a[0],
            transform_of(kw, Some(ParameterTransform::Softplus)),
            init,
        )
        .rounded_to_f32()
        .into(),
        "Interval" => {
            let t = transform_of(kw, Some(ParameterTransform::Sigmoid));
            Interval::new(a[0], a[1], t, None, init)
                .unwrap()
                .rounded_to_f32()
                .into()
        }
        other => panic!("unknown constraint {other}"),
    }
}

fn kw_prior(kw: &Value, key: &str) -> Option<Prior> {
    kw.get(key).map(|v| prior_of(&v["__prior__"]))
}

fn kw_constraint(kw: &Value, key: &str) -> Option<Constraint> {
    kw.get(key).map(|v| constraint_of(&v["__constraint__"]))
}

fn kw_usize(kw: &Value, key: &str) -> Option<usize> {
    kw.get(key).and_then(Value::as_u64).map(|v| v as usize)
}

fn with(
    mut node: KernelNode,
    kw: &Value,
    param: &str,
    prior: &str,
    constraint: &str,
) -> KernelNode {
    if let Some(c) = kw_constraint(kw, constraint) {
        node = node.with_constraint(param, c).unwrap();
    }
    if let Some(p) = kw_prior(kw, prior) {
        node = node.with_prior(param, p).unwrap();
    }
    node
}

fn lengthscale(node: KernelNode, kw: &Value) -> KernelNode {
    with(
        node,
        kw,
        "raw_lengthscale",
        "lengthscale_prior",
        "lengthscale_constraint",
    )
}

fn matern(nu: f64, ard: Option<usize>, prior: Option<Prior>, c: Option<Constraint>) -> KernelNode {
    let mut n = KernelNode::stationary(KernelKind::matern(nu).unwrap(), ard).unwrap();
    if let Some(p) = prior {
        n = n.with_prior("raw_lengthscale", p).unwrap();
    }
    if let Some(c) = c {
        n = n.with_constraint("raw_lengthscale", c).unwrap();
    }
    n
}

fn node(spec: &Value) -> KernelNode {
    let ty = spec["type"].as_str().unwrap();
    let kw = &spec["kwargs"];
    let args: Vec<&Value> = spec["args"].as_array().unwrap().iter().collect();
    let ard = kw_usize(kw, "ard_num_dims");
    let child = |v: &Value| node(&v["__kernel__"]);
    let mut n = match ty {
        "RBFKernel" => lengthscale(KernelNode::stationary(KernelKind::Rbf, ard).unwrap(), kw),
        "MaternKernel" => {
            let nu = kw.get("nu").map_or(2.5, num);
            lengthscale(
                KernelNode::stationary(KernelKind::matern(nu).unwrap(), ard).unwrap(),
                kw,
            )
        }
        "RQKernel" => {
            let n = lengthscale(KernelNode::rational_quadratic(ard).unwrap(), kw);
            with(n, kw, "raw_alpha", "-", "alpha_constraint")
        }
        "PeriodicKernel" => {
            let n = lengthscale(KernelNode::periodic(ard).unwrap(), kw);
            with(
                n,
                kw,
                "raw_period_length",
                "period_length_prior",
                "period_length_constraint",
            )
        }
        "LinearKernel" => with(
            KernelNode::linear(ard).unwrap(),
            kw,
            "raw_variance",
            "variance_prior",
            "variance_constraint",
        ),
        "PolynomialKernel" => with(
            KernelNode::polynomial(num(&kw["power"])).unwrap(),
            kw,
            "raw_offset",
            "offset_prior",
            "offset_constraint",
        ),
        "CosineKernel" => with(
            KernelNode::cosine(),
            kw,
            "raw_period_length",
            "period_length_prior",
            "period_length_constraint",
        ),
        "IndexKernel" => {
            let mut n = KernelNode::index(
                kw_usize(kw, "num_tasks").unwrap(),
                kw_usize(kw, "rank").unwrap_or(1),
            )
            .unwrap();
            n = with(n, kw, "raw_var", "-", "var_constraint");
            if let Some(p) = kw.get("prior") {
                let p = &p["__prior__"];
                n = if p[0] == "LKJCovariancePrior" {
                    let a = p[1].as_array().unwrap();
                    n.with_task_prior(MatrixPrior::LkjCovariance {
                        n: a[0].as_u64().unwrap() as usize,
                        eta: num(&a[1]) as f32 as f64,
                        sd_prior: prior_of(&a[2]["__prior__"]),
                    })
                    .unwrap()
                } else {
                    n.with_task_prior(MatrixPrior::Elementwise(prior_of(p)))
                        .unwrap()
                };
            }
            n
        }
        "PositiveIndexKernel" => {
            let mut n = KernelNode::positive_index(
                kw_usize(kw, "num_tasks").unwrap(),
                kw_usize(kw, "rank").unwrap_or(1),
                kw_usize(kw, "target_task_index").unwrap_or(0),
                kw.get("unit_scale_for_target")
                    .and_then(Value::as_bool)
                    .unwrap_or(true),
            )
            .unwrap();
            n = with(n, kw, "raw_var", "-", "var_constraint");
            if let Some(p) = kw_prior(kw, "task_prior") {
                n = n.with_task_prior(MatrixPrior::Elementwise(p)).unwrap();
            }
            n
        }
        "CategoricalKernel" => lengthscale(KernelNode::categorical(ard).unwrap(), kw),
        "DownsamplingKernel" => {
            let n = with(
                KernelNode::downsampling(),
                kw,
                "raw_power",
                "power_prior",
                "power_constraint",
            );
            with(n, kw, "raw_offset", "offset_prior", "offset_constraint")
        }
        "ExponentialDecayKernel" => {
            let n = lengthscale(KernelNode::exponential_decay(ard).unwrap(), kw);
            let n = with(n, kw, "raw_power", "power_prior", "power_constraint");
            with(n, kw, "raw_offset", "offset_prior", "offset_constraint")
        }
        "InfiniteWidthBNNKernel" => KernelNode::infinite_width_bnn(
            kw_usize(kw, "depth").unwrap_or(3),
            kw.get("acos_eps").map_or(1e-7, num),
        )
        .unwrap(),
        "LinearTruncatedFidelityKernel" => {
            let fid: Vec<usize> = kw["fidelity_dims"]
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_u64().unwrap() as usize)
                .collect();
            let dimension = match kw.get("active_dims") {
                Some(a) => a.as_array().unwrap().len(),
                None => kw_usize(kw, "dimension").unwrap(),
            };
            let nu = kw.get("nu").map_or(2.5, num);
            let k = dimension - fid.len();
            let unbiased = match kw.get("covar_module_unbiased") {
                Some(v) => child(v),
                None => matern(
                    nu,
                    Some(k),
                    Some(
                        kw_prior(kw, "lengthscale_prior_unbiased")
                            .unwrap_or_else(|| Prior::gamma(3.0, 6.0).unwrap().rounded_to_f32()),
                    ),
                    kw_constraint(kw, "lengthscale_constraint_unbiased"),
                ),
            };
            let biased = match kw.get("covar_module_biased") {
                Some(v) => child(v),
                None => matern(
                    nu,
                    Some(k),
                    Some(
                        kw_prior(kw, "lengthscale_prior_biased")
                            .unwrap_or_else(|| Prior::gamma(6.0, 2.0).unwrap().rounded_to_f32()),
                    ),
                    kw_constraint(kw, "lengthscale_constraint_biased"),
                ),
            };
            let n = KernelNode::linear_truncated_fidelity(fid, unbiased, biased).unwrap();
            with(n, kw, "raw_power", "power_prior", "power_constraint")
        }
        "OrthogonalAdditiveKernel" => {
            let dim = kw_usize(kw, "dim").unwrap();
            let per_dim = kw
                .get("per_dim_lengthscales")
                .and_then(Value::as_bool)
                .unwrap_or(true);
            let base = match kw.get("base_kernel") {
                Some(v) => child(v),
                None => KernelNode::stationary(KernelKind::Rbf, None).unwrap(),
            };
            let coeff = kw_constraint(kw, "coeff_constraint").unwrap_or_else(Constraint::positive);
            let second = kw
                .get("second_order")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            let mut n = KernelNode::orthogonal_additive(
                dim,
                base,
                per_dim,
                kw_usize(kw, "quad_deg").unwrap_or(32),
                second,
                kw.get("check_hypercube")
                    .and_then(Value::as_bool)
                    .unwrap_or(true),
                coeff,
            )
            .unwrap();
            let exact = kw.get("dtype").is_some();
            let round = |v: f64| if exact { v } else { v as f32 as f64 };
            let log_d = (dim as f64).ln();
            n = n.with_default_raw("raw_coeffs_1", round(-log_d)).unwrap();
            if second {
                n = n
                    .with_default_raw("raw_coeffs_2", round(-2.0 * log_d))
                    .unwrap();
            }
            for (param, key) in [
                ("raw_offset", "offset_prior"),
                ("raw_coeffs_1", "coeffs_1_prior"),
                ("raw_coeffs_2", "coeffs_2_prior"),
            ] {
                if let Some(p) = kw_prior(kw, key) {
                    n = n.with_prior(param, p).unwrap();
                }
            }
            n
        }
        "ScaleKernel" => with(
            KernelNode::scale(child(args[0])),
            kw,
            "raw_outputscale",
            "outputscale_prior",
            "outputscale_constraint",
        ),
        "AdditiveKernel" => KernelNode::additive(args.iter().map(|a| child(a)).collect()).unwrap(),
        "ProductKernel" => KernelNode::product(args.iter().map(|a| child(a)).collect()).unwrap(),
        other => panic!("unknown kernel {other}"),
    };
    if let Some(dims) = kw.get("active_dims") {
        let dims: Vec<usize> = dims
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_u64().unwrap() as usize)
            .collect();
        n = n.with_active_dims(dims).unwrap();
    }
    n
}

// ----------------------------------------------------------------------
// The test
// ----------------------------------------------------------------------

fn load() -> Vec<Case> {
    let dir: PathBuf = fixture_dir().join("6a_kernels");
    let mut paths: Vec<PathBuf> = std::fs::read_dir(&dir)
        .expect("fixture directory exists")
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|e| e == "json"))
        .collect();
    paths.sort();
    assert!(!paths.is_empty(), "no 6a_kernels fixtures");
    paths
        .iter()
        .map(|p| {
            let text = std::fs::read_to_string(p).unwrap();
            serde_json::from_str(&text).unwrap_or_else(|e| panic!("{}: {e}", p.display()))
        })
        .collect()
}

fn build(c: &Case, train_x: &[Vec<f64>]) -> BatchedMultiOutputGP {
    let options = BatchedMultiOutputGPOptions {
        train_yvar: c
            .train_yvar
            .as_ref()
            .filter(|_| c.fixed_noise)
            .map(|v| vec![matrix(v)]),
        outcome_transform: if c.standardize {
            OutcomeTransformChoice::Default
        } else {
            OutcomeTransformChoice::None
        },
        covar_tree: Some(node(&c.spec)),
        ..Default::default()
    };
    BatchedMultiOutputGP::new(
        vec![matrix(train_x)],
        vec![matrix(&c.train_y)],
        Vec::new(),
        options,
    )
    .unwrap()
}

/// Whether a parameter is initialized randomly by GPyTorch.
fn random_init(name: &str) -> bool {
    name.ends_with("covar_factor") || name.ends_with(".raw_var")
}

fn grad_err(a: &[f64], e: &[f64]) -> f64 {
    let scale = e.iter().fold(0.0f64, |m, v| m.max(v.abs())).max(1e-300);
    a.iter()
        .zip(e)
        .map(|(x, y)| (x - y).abs() / scale)
        .fold(0.0, f64::max)
}

#[test]
fn kernel_trees_match_botorch() {
    let mut report = Report::default();
    for c in load() {
        let name = c.name.as_str();
        let mut gp = build(&c, &c.train_x);
        let shapes = gp.parameter_shapes();
        assert_eq!(shapes, c.param_names, "{name}: parameter names and shapes");
        let bounds: Vec<(f64, f64)> = c.bounds.iter().map(|(a, b)| (num(a), num(b))).collect();
        let rs_bounds = gp.raw_parameter_bounds();
        let bounds_ok = rs_bounds
            .iter()
            .zip(&bounds)
            .all(|(a, b)| a.0 == b.0 && a.1 == b.1);
        report.check(name, "bounds (exact)", f64::from(u8::from(!bounds_ok)), 0.0);
        // Default raw parameters (except GPyTorch's random initial values).
        let init = gp.raw_parameters();
        let mut off = 0;
        let mut init_err = 0.0f64;
        for (pname, shape) in &shapes {
            let k: usize = shape.iter().product();
            if !random_init(pname) {
                for j in off..off + k {
                    init_err = init_err.max((init[j] - c.default_raw[j]).abs());
                }
            }
            off += k;
        }
        report.check(name, "default raw parameters", init_err, 0.0);
        gp.set_raw_parameters(&c.default_raw).unwrap();
        let (v, g) = gp.mll_values_and_grad(&c.default_raw).unwrap();
        report.check_slices(name, "default MLL", &v, &c.default_mll.value, VALUE_TOL);
        report.check(
            name,
            "default MLL gradient",
            grad_err(g.as_slice(), &c.default_mll.grad),
            GRAD_TOL,
        );
        // Random parameters.
        gp.set_raw_parameters(&c.raw).unwrap();
        let (v, g) = gp.mll_values_and_grad(&c.raw).unwrap();
        report.check_slices(name, "MLL", &v, &c.mll.value, VALUE_TOL);
        report.check(
            name,
            "MLL gradient",
            grad_err(g.as_slice(), &c.mll.grad),
            GRAD_TOL,
        );
        let k_expected: Vec<f64> = flatten_value(&c.k_train);
        let mut k_actual = Vec::new();
        for e in 0..gp.num_elements() {
            let el = &gp.models()[e];
            let covar = el.covar().unwrap();
            let p = covar.prepare(el.transformed_train_inputs()).unwrap();
            let k = covar.symmetric(&p);
            k_actual.extend(common::matrix_rows(&k));
        }
        report.check_slices(name, "kernel matrix", &k_actual, &k_expected, VALUE_TOL);

        // q = 1 posteriors (diag=True mode) and their input gradients.
        let pf = &c.posterior;
        let m = c.m;
        let (mut mean, mut var, mut var_noisy) = (Vec::new(), Vec::new(), Vec::new());
        let (mut dmean, mut dvar) = (vec![0.0; pf.x.len() * pf.x[0].len()], Vec::new());
        dvar.resize(dmean.len(), 0.0);
        let d = pf.x[0].len();
        for (i, x) in pf.x.iter().enumerate() {
            for t in 0..m {
                let gp_t = gp.model(0, t);
                let (mu, v, dm, dv) = gp_t.posterior_q1_with_grad(x).unwrap();
                mean.push(mu);
                var.push(v);
                var_noisy.push(v + gp_t.observation_noise());
                for j in 0..d {
                    dmean[i * d + j] += dm[j];
                    dvar[i * d + j] += dv[j];
                }
            }
        }
        report.check_slices(
            name,
            "q=1 posterior mean",
            &mean,
            &common::flatten(&pf.mean),
            VALUE_TOL,
        );
        report.check_slices(
            name,
            "q=1 posterior variance",
            &var,
            &common::flatten(&pf.variance),
            VALUE_TOL,
        );
        report.check_slices(
            name,
            "q=1 noisy posterior variance",
            &var_noisy,
            &common::flatten(&pf.variance_noisy),
            VALUE_TOL,
        );
        report.check(
            name,
            "q=1 d mean / dx",
            grad_err(&dmean, &common::flatten(&pf.dmean_dx)),
            GRAD_TOL,
        );
        report.check(
            name,
            "q=1 d variance / dx",
            grad_err(&dvar, &common::flatten(&pf.dvariance_dx)),
            GRAD_TOL,
        );

        // Joint q = 3 posteriors per output and the gradient of a weighted sum.
        let xj = matrix(&pf.joint_x);
        let q = xj.nrows();
        let mut grad = Matrix::zeros(q, d);
        for t in 0..m {
            let gp_t = gp.model(0, t);
            let post = gp_t.posterior(&xj, false).unwrap();
            let noisy = gp_t.posterior(&xj, true).unwrap();
            report.check_slices(
                name,
                "joint posterior mean",
                post.mean.as_slice(),
                &pf.joint_mean[t],
                VALUE_TOL,
            );
            report.check_slices(
                name,
                "joint posterior covariance",
                &common::matrix_rows(&post.covariance),
                &common::flatten(&pf.joint_covariance[t]),
                VALUE_TOL,
            );
            report.check_slices(
                name,
                "joint noisy posterior covariance",
                &common::matrix_rows(&noisy.covariance),
                &common::flatten(&pf.joint_covariance_noisy[t]),
                VALUE_TOL,
            );
            let wm = Vector::from_vec(pf.weights_mean[t].clone());
            let wc = matrix(&pf.weights_cov[t]);
            grad += gp_t.joint_posterior_vjp(&xj, 0..q, &wm, &wc).unwrap();
        }
        report.check(
            name,
            "joint d (weighted sum) / dx",
            grad_err(&common::matrix_rows(&grad), &common::flatten(&pf.djoint_dx)),
            GRAD_TOL,
        );

        // Fits from the default parameters.
        if let Some(f) = &c.fit {
            let mut fitted = build(&c, &c.train_x);
            fitted.set_raw_parameters(&c.default_raw).unwrap();
            let r = fit_gpytorch_mll(&mut fitted, FitOptions::default()).unwrap();
            // Outcomes of first attempts only: retries start from prior
            // samples, which the two libraries draw from different RNGs.
            let bt: Vec<f64> = std::iter::once((f.loss, f.attempts))
                .chain(
                    f.twin_losses
                        .iter()
                        .copied()
                        .zip(f.twin_attempts.iter().copied()),
                )
                .filter(|&(_, a)| a == 1)
                .map(|(l, _)| l)
                .collect();
            let own_attempts = r.results[0].attempts;
            let rs: Vec<f64> = std::iter::once((r.loss, own_attempts))
                .chain(f.twin_train_x.iter().map(|x| {
                    let mut twin = build(&c, x);
                    twin.set_raw_parameters(&c.default_raw).unwrap();
                    let t = fit_gpytorch_mll(&mut twin, FitOptions::default()).unwrap();
                    (t.loss, t.results[0].attempts)
                }))
                .filter(|&(_, a)| a == 1)
                .map(|(l, _)| l)
                .collect();
            let bt_best = bt.iter().copied().fold(f64::INFINITY, f64::min);
            let bt_worst = bt.iter().copied().fold(f64::NEG_INFINITY, f64::max);
            let rs_best = rs.iter().copied().fold(f64::INFINITY, f64::min);
            let spread = bt
                .iter()
                .copied()
                .filter(|&l| l <= bt_best + FIT_CLUSTER)
                .fold(bt_best, f64::max)
                - bt_best;
            let tol = FIT_TOL.max(10.0 * spread);
            if bt_worst - bt_best > CHAOTIC_RANGE {
                // A chaotic likelihood: BoTorch's own outcomes are spread over
                // many optima, compared statistically.
                let (bt_q, rs_q) = (quantiles(&bt), quantiles(&rs));
                report.check(
                    name,
                    "fit (chaotic): best above BoTorch's median",
                    (rs_q.0 - bt_q.2).max(0.0),
                    FIT_TOL,
                );
                report.check(
                    name,
                    "fit (chaotic): median above BoTorch's upper quartile",
                    (rs_q.2 - bt_q.3).max(0.0),
                    FIT_TOL,
                );
            } else {
                report.check(
                    name,
                    "fit: best loss above BoTorch's best (scaled)",
                    (rs_best - bt_best).max(0.0) / tol,
                    1.0,
                );
                if own_attempts == 1 {
                    report.check(
                        name,
                        "fit: loss above BoTorch's worst (scaled)",
                        (r.loss - bt_worst).max(0.0) / tol,
                        1.0,
                    );
                }
            }
            let diff = fitted
                .raw_parameters()
                .iter()
                .zip(&f.raw_params)
                .map(|(a, b)| (a - b).abs())
                .fold(0.0, f64::max);
            println!(
                "{name:26} fit: loss {:+.10} (BoTorch {:+.10}), iterations {} (BoTorch {}), \
                 attempts {own_attempts} (BoTorch {}), max parameter difference {diff:.1e}, \
                 first-attempt outcomes: BoTorch [{bt_best:+.10}, {bt_worst:+.10}] ({} of 17), \
                 botorch_rs best {rs_best:+.10} ({} of 17), spread {spread:.1e}",
                r.loss,
                f.loss,
                r.results[0].iterations,
                f.iterations,
                f.attempts,
                bt.len(),
                rs.len()
            );
        }
    }
    report.finish("6a kernels: kernel trees in SingleTaskGP");
}

fn flatten_value(v: &Value) -> Vec<f64> {
    match v {
        Value::Array(a) => a.iter().flat_map(flatten_value).collect(),
        other => vec![num(other)],
    }
}

#[test]
fn every_rel_err_helper_is_used() {
    // Keeps the shared helpers in use for this test crate.
    assert_eq!(rel_err(&[1.0], &[1.0]), 0.0);
}
